{
  "summary": "The function fn_01 computes a CRC-32 checksum.",
  "proposed_name": "fn_01",
  "algorithm": "Implements CRC-32.",
  "self_confidence": 1.0,
  "claims": [
    {
      "id": "ALG",
      "type": "ALG",
      "text": "Implements CRC-32.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "CONST",
      "type": "CONST",
      "text": "The CRC-32 polynomial uses the constant 0xEDB88320.",
      "asserted_values": ["0xEDB88320"],
      "confidence": 1.0
    },
    {
      "id": "IO",
      "type": "IO",
      "text": "Returns 0xFFFFFFFFFFFFFFFF when len == 0.",
      "asserted_values": [],
      "confidence": 1.0,
      "io": {
        "when": "len == 0",
        "returns": "0xFFFFFFFFFFFFFFFF"
      }
    },
    {
      "id": "IO",
      "type": "IO",
      "text": "Returns the computed CRC-32 value when len > 0.",
      "asserted_values": [],
      "confidence": 1.0,
      "io": {
        "when": "len > 0",
        "returns": "computed CRC-32 value"
      }
    },
    {
      "id": "SIDE",
      "type": "SIDE",
      "text": "Does not write to out.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "CF",
      "type": "CF",
      "text": "Iterates over each byte in the input buffer.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "CF",
      "type": "CF",
      "text": "Iterates over each bit in the current byte.",
      "asserted_values": [],
      "confidence": 1.0
    }
  ],
  "recovered_c": "uint64_t fn_01(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  uint32_t h = 0xffffffff;\n  for (size_t i = 0; i < len; i++) {\n    h = h ^ in[i];\n    for (uint8_t b = 0; b < 8; b++) {\n      h = -(h & 1) & 0xedb88320 ^ h >> 1;\n    }\n  }\n  return (uint64_t)~h;\n}"
}
